alter table cp_instances add column last_measured_at timestamptz;
create function public.cp_validate_profile(c jsonb) returns void language plpgsql immutable set search_path=public as $$
declare band jsonb;r jsonb;expected_ int=1;last_ int;group_ text;v numeric;
begin
 if jsonb_typeof(c->'bands')<>'array' or jsonb_array_length(c->'bands') not between 1 and 30 or length(coalesce(c->>'source',''))<5 or length(coalesce(c->>'context',''))<10 or nullif(c->>'version','') is null then raise exception 'A source, context, version and age bands are required';end if;
 perform (c->>'effectiveDate')::date;
 for band in select * from jsonb_array_elements(c->'bands') loop
 if (band->>'from')::int<>expected_ or last_ is null and expected_>100000 then raise exception 'Age bands must be consecutive';end if;
 last_=nullif(band->>'to','')::int;if last_ is not null and last_<(band->>'from')::int then raise exception 'Invalid age band';end if;
 expected_=coalesce(last_,100000)+1;
 for group_ in select unnest(array['temperature','humidity']) loop r=band->group_;
 if not (coalesce((r->>'criticalMin')::numeric<=(r->>'warningMin')::numeric and (r->>'warningMin')::numeric<=(r->>'desiredMin')::numeric and (r->>'desiredMin')::numeric<=(r->>'recoveryMin')::numeric and (r->>'recoveryMin')::numeric<(r->>'recoveryMax')::numeric and (r->>'recoveryMax')::numeric<=(r->>'desiredMax')::numeric and (r->>'desiredMax')::numeric<=(r->>'warningMax')::numeric and (r->>'warningMax')::numeric<=(r->>'criticalMax')::numeric,false)) then raise exception 'Invalid desired/warning/critical/recovery bands';end if;
 end loop;end loop;
 if last_ is not null then raise exception 'Final age band must cover delayed pickup';end if;
 for group_ in select unnest(array['responseMinutes','escalateMinutes','persistenceCount','recoveryCount','rapidTemperatureDelta','rapidWindowMinutes','intakeDropPct','mortalityCriticalPct']) loop v=(c#>>array['rules',group_])::numeric;if v is null or v<=0 or v>1440 then raise exception 'Invalid rule: %',group_;end if;end loop;
 if not coalesce((c#>>'{limits,ammoniaRecovery}')::numeric<(c#>>'{limits,ammoniaWarning}')::numeric and (c#>>'{limits,ammoniaWarning}')::numeric<=(c#>>'{limits,ammoniaCritical}')::numeric and (c#>>'{limits,co2Recovery}')::numeric<(c#>>'{limits,co2Warning}')::numeric and (c#>>'{limits,co2Warning}')::numeric<=(c#>>'{limits,co2Critical}')::numeric and (c#>>'{limits,phMin}')::numeric<(c#>>'{limits,phMax}')::numeric,false) then raise exception 'Invalid consistent action/recovery limits';end if;
end $$;
revoke all on function cp_validate_profile(jsonb) from public,anon,authenticated;

create or replace function public.cp_save_profile(o uuid,c jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare n uuid;begin if not cp_admin(o) then raise exception 'Only organization admins may approve management profiles';end if;if jsonb_typeof(c->'bands')<>'array' or jsonb_array_length(c->'bands')=0 or nullif(c->>'source','') is null or nullif(c->>'version','') is null or nullif(c->>'effectiveDate','') is null then raise exception 'Versioned source and age bands are required';end if;perform cp_validate_profile(c);insert into cp_profiles(org_id,config,approved_by,approved_at) values(o,c,case when (c->>'approved')::boolean then auth.uid() end,case when (c->>'approved')::boolean then now() end) returning id into n;return n;end $$;
create or replace function public.cp_save_schedule(o uuid,c jsonb,s uuid default null,expected_revision int default null) returns uuid language plpgsql security definer set search_path=public as $$
declare p cp_profiles; r records; targetfarm records; m uuid; w uuid; n uuid; z text;
begin
 if not cp_admin(o) then raise exception 'Only organization admins can configure schedules';end if;
 select * into r from records where id=(c->>'scopeId')::uuid and org_id=o and kind=c->>'scope';if not found then raise exception 'Invalid farm/shed/batch scope';end if;
 select * into targetfarm from records where org_id=o and kind='farm' and id=case when r.kind='farm' then r.id else (r.data->>'farm')::uuid end;
 z=coalesce(targetfarm.data->>'timezone',r.data->>'timezone','Asia/Kolkata');perform now() at time zone z;
 c=jsonb_set(c,'{timezone}',to_jsonb(z));
 select * into p from cp_profiles where id=(c->>'profileId')::uuid and org_id=o;if not found or (coalesce((c->>'enabled')::boolean,false) and p.approved_at is null) then raise exception 'Enabled schedules require an approved profile';end if;
 w=(c->>'worker')::uuid;m=(c->>'manager')::uuid;
 if not exists(select 1 from memberships where org_id=o and user_id=w and role in ('owner','manager','worker')) or not exists(select 1 from memberships where org_id=o and user_id=m and role in ('owner','manager')) then raise exception 'Choose an organization worker and backup manager';end if;
 if exists(select 1 from memberships where org_id=o and user_id=w and role='worker') and ((r.kind='farm' and exists(select 1 from records shed where shed.org_id=o and shed.kind='shed' and shed.data->>'farm'=r.id::text and not exists(select 1 from assignments where org_id=o and user_id=w and shed_id=shed.id))) or (r.kind<>'farm' and not exists(select 1 from assignments where org_id=o and user_id=w and shed_id=case when r.kind='shed' then r.id else (r.data->>'shed')::uuid end))) then raise exception 'Worker needs an assignment for every shed covered by this schedule';end if;
 if c->>'intervalMinutes' is not null and (c->>'intervalMinutes')::int not between 15 and 1440 then raise exception 'Invalid custom interval';end if;if exists(select 1 from jsonb_array_elements_text(c->'times') t where t !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') then raise exception 'Invalid checkpoint time';end if;
 if jsonb_typeof(c->'times')<>'array' or jsonb_array_length(c->'times')=0 or (c->>'windowMinutes')::int not between 1 and 720 or (c->>'leadMinutes')::int not between 0 and 240 or (c->>'escalateMinutes')::int not between 1 and 1440 then raise exception 'Invalid timing configuration';end if;
 if s is null then insert into cp_schedules(org_id,scope,scope_id,config) values(o,c->>'scope',(c->>'scopeId')::uuid,c) returning id into n;
 else update cp_schedules set config=c,scope=c->>'scope',scope_id=(c->>'scopeId')::uuid,revision=revision+1,updated_at=now() where id=s and org_id=o and revision=expected_revision returning id into n;if n is null then raise exception 'Schedule changed: reload before saving';end if;update cp_instances set status='cancelled' where schedule_id=s and scheduled_at>now() and status in ('upcoming','due') and not exists(select 1 from cp_readings where instance_id=cp_instances.id);end if;return n;
end $$;
create or replace function public.cp_tick_batch(b uuid) returns void language plpgsql security definer set search_path=public as $$
declare i cp_instances; r cp_readings; a cp_alerts; alertid uuid; state_ text; first_ timestamptz;
begin
 perform cp_generate(b);
 for i in select * from cp_instances where batch_id=b and status<>'cancelled' and scheduled_at<now()+interval '1 day' for update skip locked loop
 select * into r from cp_readings where instance_id=i.id and payload->>'access'='accessible' order by measured_at desc limit 1;
 state_=case when r.id is not null then case when r.measured_at>i.deadline_at then 'late' else 'completed' end when now()>i.escalate_at then 'missed' when now()>i.deadline_at then 'late' when now()>=i.scheduled_at-make_interval(mins=>(i.snapshot->>'leadMinutes')::int) then 'due' else 'upcoming' end;
 if state_<>i.status or i.last_measured_at is distinct from r.measured_at then update cp_instances set last_measured_at=r.measured_at,status=state_ where id=i.id;end if;
 if r.id is not null then update cp_alerts set status='resolved',resolved_at=now(),resolution='The checkpoint received an actual measurement. Late measurement/upload timestamps remain visible.',updated_at=now() where instance_id=i.id and rule_key='missed:'||i.id::text and status<>'resolved';continue;end if;
 if state_='due' then perform cp_notify(i.org_id,b,i.worker_id,'checkpoint_due','Checkpoint due: '||to_char(i.scheduled_at at time zone i.timezone,'YYYY-MM-DD HH24:MI')||' '||i.timezone,i.id,'due:'||i.id::text);end if;
 if now()>i.deadline_at then
 perform cp_notify(i.org_id,b,i.worker_id,'checkpoint_late','Checkpoint completion window has passed. Record actual measurement time or an access reason.',i.id,'late:'||i.id::text);
 if not exists(select 1 from cp_alerts where rule_key='missed:'||i.id::text) then
 insert into cp_alerts(org_id,batch_id,instance_id,rule_key,severity,title,why,checks,observed,thresholds,source,assigned_to,manager_id,recheck_at) values(i.org_id,b,i.id,'missed:'||i.id::text,'warning','Overdue / missed checkpoint','The scheduled shed condition has not been established.','Ask the worker or backup manager to check the shed, preserve actual times and submit a measurement or safe-access reason.',jsonb_build_object('scheduledAt',i.scheduled_at,'deadline',i.deadline_at),jsonb_build_object('completionWindow',i.snapshot->'windowMinutes','escalationDelay',i.snapshot->'escalateMinutes'),'Configured checkpoint schedule',i.worker_id,i.manager_id,i.escalate_at);end if;
 end if;
 if now()>i.escalate_at and i.escalated_at is null then update cp_instances set escalated_at=now() where id=i.id;update cp_alerts set escalated_at=now() where instance_id=i.id and rule_key='missed:'||i.id::text;perform cp_notify(i.org_id,b,i.manager_id,'checkpoint_escalated','Missed checkpoint escalated to backup manager.',i.id,'escalate:'||i.id::text);end if;
 end loop;
 for a in select * from cp_alerts where batch_id=b and status<>'resolved' and escalated_at is null and recheck_at<now() for update skip locked loop
 if now()>a.recheck_at+make_interval(mins=>coalesce((select (snapshot#>>'{profile,rules,escalateMinutes}')::int from cp_instances where id=a.instance_id),30)) then update cp_alerts set escalated_at=now(),updated_at=now() where id=a.id;perform cp_notify(a.org_id,b,a.manager_id,'alert_escalated','Unresolved alert escalated: '||a.title,a.id,'escalated-alert:'||a.id::text);end if;end loop;
end $$;
create or replace function public.cp_submit(b uuid,p jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare i cp_instances; r cp_readings; old_ cp_readings; rid uuid; k text; v jsonb; n numeric; measured_ timestamptz; existing uuid; profile_ jsonb; approvedage int;request_hash text;prior_request cp_requests;
begin
 select * into i from cp_instances where id=(p->>'instanceId')::uuid and batch_id=b;if not found or not cp_staff(i.org_id,b) or org_role(i.org_id)='veterinarian' then raise exception 'Checkpoint is not accessible for recording';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||(p->>'requestId'),717));
 request_hash=encode(extensions.digest(p::text,'sha256'),'hex');select * into prior_request from cp_requests where user_id=auth.uid() and request_id=(p->>'requestId')::uuid;if found then if prior_request.payload_hash<>request_hash then raise exception 'Request identifier reused with changed content; review draft before retrying';end if;return prior_request.reading_id;end if;
 perform pg_advisory_xact_lock(hashtextextended(b::text,716));
 select id into existing from cp_readings where actor=auth.uid() and request_id=(p->>'requestId')::uuid;if existing is not null then return existing;end if;
 if i.status='cancelled' or exists(select 1 from records where id=b and data->>'status'='Completed') then raise exception 'Schedule changed or batch is completed. Keep draft and review with the manager.';end if;
 measured_=(p->>'measuredAt')::timestamptz;if measured_>now()+interval '5 minutes' or (measured_ at time zone i.timezone)::date<(select (data->>'placement')::date from records where id=b) or measured_<i.scheduled_at-make_interval(mins=>(i.snapshot->>'leadMinutes')::int) then raise exception 'Measurement time is in the future or before the checkpoint opens';end if;
 if p->>'access' not in ('accessible','unable_to_access') or p->>'access'='unable_to_access' and nullif(trim(p->>'accessReason'),'') is null then raise exception 'Record access status and reason';end if;
 if jsonb_typeof(p->'values')<>'object' or jsonb_typeof(p->'states')<>'object' then raise exception 'Readings required';end if;
 for k,v in select * from jsonb_each(p->'values') loop
 if k not in ('temperature','humidity','ammonia','co2','waterTemperature','waterPh','waterAmount','feedAmount','deaths','culls','lux') then raise exception 'Unknown measurement';end if;
 if v->>'state' not in ('measured','not_measured','instrument_unavailable','estimated') or v->>'method' not in ('manual','sensor','estimated') then raise exception 'Measurement provenance required';end if;
 if v->>'value' is not null then n=(v->>'value')::numeric;if n<0 and k<>'temperature' or k='temperature' and n not between -10 and 60 or k='humidity' and n>100 or k='waterPh' and n>14 or k='ammonia' and n>500 or k='co2' and n>100000 or k in ('deaths','culls') and mod(n,1)<>0 then raise exception 'Invalid numeric reading';end if;end if;
 if v->>'state'='measured' and v->>'value' is null or v->>'state' in ('not_measured','instrument_unavailable') and v->>'value' is not null then raise exception 'Missing is not zero';end if;
 if k='ammonia' and (v->>'state'='estimated' or v->>'method'='estimated') then raise exception 'Ammonia must not be estimated from smell or images';end if;
 end loop;
 for k in select jsonb_array_elements_text(i.snapshot->'required') loop if k in ('temperature','humidity','ammonia','co2','waterTemperature','waterPh','waterAmount','feedAmount','deaths','culls','lux') and cp_num(p,k) is null and nullif(trim(coalesce(p#>>array['values',k,'reason'],'')),'') is null and p->>'access'<>'unable_to_access' then if k<>'waterPh' or not exists(select 1 from cp_readings x where x.batch_id=b and x.measured_at<measured_ and x.measured_at>measured_-make_interval(hours=>coalesce((i.snapshot->>'phEveryHours')::int,24)) and cp_num(x.payload,'waterPh') is not null) then raise exception 'Explain missing required measurement: %',k;end if;end if;end loop;
 if jsonb_array_length(coalesce(p->'photos','[]'))>6 then raise exception 'Maximum six evidence photos';end if;
 for k in select jsonb_array_elements_text(coalesce(p->'photos','[]')) loop if k not like i.org_id::text||'/'||b::text||'/%' or k like '%..%' or array_length(string_to_array(k,'/'),1)<>3 then raise exception 'Photo outside authorized batch';end if;if not exists(select 1 from storage.objects where bucket_id='flock-photos' and name=k) then raise exception 'Private photo evidence not found';end if;end loop;
 if nullif(p->>'intervalStart','')::timestamptz>=measured_ then raise exception 'Invalid interval';end if;
 profile_=i.snapshot->'profile';
 if p->>'readingId' is not null then
 select * into old_ from cp_readings where id=(p->>'readingId')::uuid and batch_id=b and instance_id=i.id;if not found or old_.revision<>(p->>'revision')::int or not(cp_admin(i.org_id) or old_.actor=auth.uid()) then raise exception 'Reading changed or correction is not permitted';end if;
 update cp_readings set payload=p,measured_at=measured_,revision=revision+1,updated_at=now() where id=old_.id returning id into rid;
 else insert into cp_readings(org_id,batch_id,instance_id,request_id,measured_at,payload,profile_snapshot) values(i.org_id,b,i.id,(p->>'requestId')::uuid,measured_,p,profile_) returning id into rid;end if;
 perform cp_evaluate(rid);
 -- A correction invalidates downstream rate derivations; recalculate in actual measurement order.
 for r in select * from cp_readings where batch_id=b and measured_at>measured_ order by measured_at loop update cp_readings set derived=cp_derive(r),revision=revision+1,updated_at=now() where id=r.id;end loop;
 if p->>'readingId' is not null then select * into r from cp_readings where batch_id=b order by measured_at desc limit 1;if r.id<>rid then perform cp_evaluate(r.id);end if;end if;
 insert into cp_requests(user_id,request_id,batch_id,reading_id,payload_hash) values(auth.uid(),(p->>'requestId')::uuid,b,rid,request_hash);return rid;
end $$;
create or replace function public.cp_evaluate(rid uuid) returns void language plpgsql security definer set search_path=public as $$
declare r cp_readings; i cp_instances; br records; band jsonb; profile jsonb; lim jsonb; rules jsonb; age int; k text; v numeric; rr jsonb; bad boolean; recovery_ boolean; sev text; temp_ numeric; rh numeric; nh numeric; co numeric; respiratory boolean; signals text[]; first_at timestamptz; prev cp_readings; df numeric; dw numeric; dm numeric; baseline_count int; lowfeed boolean=false; lowwater boolean=false; highfeed boolean=false; highwater boolean=false; mortalitybad boolean=false; sources jsonb; n numeric;
begin
 select * into r from cp_readings where id=rid;select * into i from cp_instances where id=r.instance_id;select * into br from records where id=r.batch_id;
 perform pg_advisory_xact_lock(hashtextextended(r.batch_id::text,716));
 r.derived=cp_derive(r);update cp_readings set derived=r.derived where id=r.id;
 -- Backfilled readings remain in charts/audits, but cannot masquerade as a current recheck.
 if exists(select 1 from cp_readings x where x.batch_id=r.batch_id and x.measured_at>r.measured_at) then
 if not exists(select 1 from cp_alerts where batch_id=r.batch_id and rule_key='historical:'||r.id::text) then insert into cp_alerts(org_id,batch_id,instance_id,rule_key,severity,title,why,checks,observed,thresholds,source,assigned_to,manager_id,measurement_at,recheck_at,history) values(i.org_id,r.batch_id,i.id,'historical:'||r.id::text,'information','Backfilled / corrected historical observation — review','A measurement arrived after newer observations; it is not evidence of current conditions and cannot satisfy current recovery.','Review the dated values against the attached profile. Arrange a new measurement if there is an unresolved concern.',r.payload->'values',i.snapshot->'profile',i.snapshot#>>'{profile,source}',i.worker_id,i.manager_id,r.measured_at,now()+interval '1 hour',jsonb_build_array(jsonb_build_object('readingId',r.id,'revision',r.revision)));end if;return;end if;
 profile=i.snapshot->'profile';lim=profile->'limits';rules=profile->'rules';age=(r.measured_at at time zone i.timezone)::date-(br.data->>'placement')::date+1;
 select x into band from jsonb_array_elements(profile->'bands') x where age>=(x->>'from')::int and (x->>'to' is null or age<=(x->>'to')::int) limit 1;
 signals=ARRAY(select jsonb_array_elements_text(r.payload->'signs'));respiratory=signals&&array['abnormal_breathing','coughing','sneezing'];
 temp_=cp_num(r.payload,'temperature',coalesce((rules->>'allowEstimated')::boolean,false));rh=cp_num(r.payload,'humidity',coalesce((rules->>'allowEstimated')::boolean,false));nh=cp_num(r.payload,'ammonia');co=cp_num(r.payload,'co2');
 for k in select jsonb_array_elements_text(i.snapshot->'required') loop
 bad=false;
 if k='waterPh' and exists(select 1 from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<r.measured_at and x.measured_at>r.measured_at-make_interval(hours=>coalesce((i.snapshot->>'phEveryHours')::int,24)) and cp_num(x.payload,'waterPh') is not null) then continue;end if;
 if k in ('temperature','humidity','ammonia','co2','waterTemperature','waterPh','waterAmount','feedAmount','deaths','culls','lux') then bad=cp_num(r.payload,k,coalesce((rules->>'allowEstimated')::boolean,false)) is null;elsif k='photo' then bad=jsonb_array_length(coalesce(r.payload->'photos','[]'))=0;else bad=coalesce(r.payload#>>array['states',k],'unknown') in ('unknown','not_measured','instrument_unavailable','');end if;
 perform cp_observe(i,r,'missing_'||k,'warning','Missing critical measurement: '||k,'A required check was not established; unknown is not zero.','Arrange a suitable instrument or safe access, ask the backup manager for help and remeasure.',jsonb_build_object('field',k,'reported',r.payload#>array['values',k],'access',r.payload->'access'),jsonb_build_object('required',true),bad,not bad);
 end loop;
 perform cp_observe(i,r,'access','critical','Unable to access shed','The shed condition has not been checked.','Contact the assigned manager and arrange safe access; do not assume the shed is normal.',jsonb_build_object('access',r.payload->'access','reason',r.payload->'accessReason'),'{}',r.payload->>'access'='unable_to_access',r.payload->>'access'='accessible');
 for k in select unnest(array['temperature','humidity']) loop
 v=case when k='temperature' then temp_ else rh end;rr=band->k;
 bad=v is not null and (v<(rr->>'warningMin')::numeric or v>(rr->>'warningMax')::numeric) or k='temperature' and exists(select 1 from jsonb_array_elements(coalesce(r.payload->'locations','[]')) l where (l->>'temperature')::numeric<(rr->>'warningMin')::numeric or (l->>'temperature')::numeric>(rr->>'warningMax')::numeric);recovery_=v is not null and v between (rr->>'recoveryMin')::numeric and (rr->>'recoveryMax')::numeric and (k<>'temperature' or not exists(select 1 from jsonb_array_elements(coalesce(r.payload->'locations','[]')) l where (l->>'temperature')::numeric not between (rr->>'recoveryMin')::numeric and (rr->>'recoveryMax')::numeric));sev=case when v<=(rr->>'criticalMin')::numeric or v>=(rr->>'criticalMax')::numeric or k='temperature' and exists(select 1 from jsonb_array_elements(coalesce(r.payload->'locations','[]')) l where (l->>'temperature')::numeric<=(rr->>'criticalMin')::numeric or (l->>'temperature')::numeric>=(rr->>'criticalMax')::numeric) then 'critical' else 'warning' end;
 perform cp_observe(i,r,k,sev,'Shed '||k||' outside approved age range','Environmental conditions can impair comfort and performance; interpret humidity and bird behavior together.','Check sensor placement, water availability, fans, heaters and cooling. For cold conditions retain necessary fresh air and consider ammonia before reducing ventilation.',jsonb_build_object('value',v,'unit',case when k='temperature' then '°C' else '%' end,'flockDay',age,'signs',signals,'locations',r.payload->'locations'),rr,coalesce(bad,false),coalesce(recovery_,false));
 end loop;
 perform cp_observe(i,r,'ammonia',case when nh>=(lim->>'ammoniaCritical')::numeric then 'critical' else 'warning' end,'High ammonia','Ammonia can irritate birds and indicate poor litter/air management.','Check measured ammonia, litter moisture, drinker leaks and fresh-air delivery; do not rely on smell.',jsonb_build_object('value',nh,'unit','ppm'),lim,coalesce(nh>=(lim->>'ammoniaWarning')::numeric,false),coalesce(nh<=(lim->>'ammoniaRecovery')::numeric,false));
 perform cp_observe(i,r,'co2',case when co>=(lim->>'co2Critical')::numeric then 'critical' else 'warning' end,'High carbon dioxide','Poor fresh-air supply or combustion can compromise air quality.','Check calibrated gas readings and ventilation/heaters with trained personnel; do not enter a suspected unsafe atmosphere.',jsonb_build_object('value',co,'unit','ppm'),lim,coalesce(co>=(lim->>'co2Warning')::numeric,false),coalesce(co<=(lim->>'co2Recovery')::numeric,false));
 v=cp_num(r.payload,'waterPh');perform cp_observe(i,r,'water_ph','warning','Water pH outside approved range','Water quality may affect consumption and treatment/vaccine handling.','Confirm the instrument, source water and approved water-quality plan. Do not add chemicals based only on this alert.',jsonb_build_object('value',v,'unit','pH'),lim,coalesce(v<(lim->>'phMin')::numeric or v>(lim->>'phMax')::numeric,false),coalesce(v between (lim->>'phMin')::numeric and (lim->>'phMax')::numeric,false));
 for k in select unnest(array['fans','ventilation','heating','cooling','waterSupply','feedSupply']) loop
 bad=r.payload#>>array['states',k] in ('failed','interrupted','unavailable','blocked');recovery_=r.payload#>>array['states',k] in ('ok','available','off_not_required');sev=case when k in ('fans','ventilation','waterSupply') then 'critical' else 'warning' end;
 perform cp_observe(i,r,'equipment_'||k,sev,k||' requires attention','Equipment or supply interruption can quickly affect flock welfare.','Check power, backup systems, flow and access. Contact the manager/technician and remeasure; do not reduce ventilation without checking air quality.',jsonb_build_object('reported',r.payload#>array['states',k]),jsonb_build_object('expected','operational/available or explicitly not required'),coalesce(bad,false),coalesce(recovery_,false));
 end loop;
 perform cp_observe(i,r,'litter','warning','Wet or caked litter','Moist litter may affect foot condition and ammonia.','Find leaks, condensation and drainage problems; follow approved litter management and ventilation practices.',jsonb_build_object('reported',r.payload#>'{states,litter}'),'{}',coalesce(r.payload#>>'{states,litter}' in ('wet','caked'),false),r.payload#>>'{states,litter}'='dry');
 perform cp_observe(i,r,'lighting','warning','Unexpected lighting deviation','Unplanned changes can disrupt feeding and rest.','Compare actual light status with the approved program; check timer/power safely before changing settings.',jsonb_build_object('lights',r.payload#>'{states,lights}','deviation',r.payload#>'{states,lightDeviation}'),'{}',r.payload#>>'{states,lightDeviation}'='yes',r.payload#>>'{states,lightDeviation}'='no');
 perform cp_observe(i,r,'behavior','warning','Abnormal bird distribution or distress','Persistent panting, huddling or abnormal breathing can reflect environmental or health concerns.','Check bird-level climate, air quality, water and equipment. Seek urgent veterinary review for severe breathing difficulty or continuing losses.',jsonb_build_object('distribution',r.payload#>'{states,distribution}','signs',signals),'{}',coalesce(signals&&array['panting','huddling','abnormal_breathing'],false) or coalesce(r.payload#>>'{states,distribution}' in ('huddling','crowding','avoiding_area'),false),not(signals&&array['panting','huddling','abnormal_breathing']) and r.payload#>>'{states,distribution}'='even');
 select * into prev from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<r.measured_at order by measured_at desc limit 1;
 bad=temp_ is not null and cp_num(prev.payload,'temperature') is not null and r.measured_at-prev.measured_at<=make_interval(mins=>(rules->>'rapidWindowMinutes')::int) and abs(temp_-cp_num(prev.payload,'temperature'))>=(rules->>'rapidTemperatureDelta')::numeric;
 perform cp_observe(i,r,'rapid_temperature','warning','Rapid temperature change','A sudden change can indicate equipment failure or a measurement problem.','Check sensor calibration/location, fan/heater transitions and bird response; assess air quality before changing ventilation.',jsonb_build_object('previous',cp_num(prev.payload,'temperature'),'current',temp_,'previousTime',prev.measured_at,'unit','°C'),jsonb_build_object('delta',rules->'rapidTemperatureDelta','minutes',rules->'rapidWindowMinutes'),coalesce(bad,false),temp_ is not null and cp_num(prev.payload,'temperature') is not null and not coalesce(bad,false));
 -- Compare only non-overlapping, similar-duration intervals, per verified opening bird/hour,
 -- within three age-days and the same local clock start-hour window. Never project partial data.
 select count(*),avg((x.derived->>'feedRate')::numeric),avg((x.derived->>'waterRate')::numeric),avg((x.derived->>'mortalityRate')::numeric) into baseline_count,df,dw,dm from (select x.* from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<r.measured_at and x.measured_at>=r.measured_at-interval '3 days' and (x.derived->>'comparable')::boolean and (x.derived->>'hours')::numeric between (r.derived->>'hours')::numeric*.75 and (r.derived->>'hours')::numeric*1.25 and least(abs(extract(hour from ((x.derived->>'intervalStart')::timestamptz at time zone i.timezone))-extract(hour from ((r.derived->>'intervalStart')::timestamptz at time zone i.timezone))),24-abs(extract(hour from ((x.derived->>'intervalStart')::timestamptz at time zone i.timezone))-extract(hour from ((r.derived->>'intervalStart')::timestamptz at time zone i.timezone))))<=1 and x.profile_snapshot=i.snapshot->'profile' order by x.measured_at desc limit 3) x;
 if baseline_count>=3 and coalesce((r.derived->>'comparable')::boolean,false) then lowfeed=df>0 and (r.derived->>'feedRate')::numeric<df*(1-(rules->>'intakeDropPct')::numeric/100);highfeed=df>0 and (r.derived->>'feedRate')::numeric>df*(1+coalesce((rules->>'intakeRisePct')::numeric,30)/100);highwater=dw>0 and (r.derived->>'waterRate')::numeric>dw*(1+coalesce((rules->>'intakeRisePct')::numeric,30)/100);lowwater=dw>0 and (r.derived->>'waterRate')::numeric<dw*(1-(rules->>'intakeDropPct')::numeric/100);end if;
 update cp_readings set derived=derived||jsonb_build_object('baselineCount',baseline_count,'baselineFeedRate',df,'baselineWaterRate',dw,'baselineLimits','Requires three matched intervals, clock window, age proximity, verified birds and no unknown inventory movements.') where id=r.id;
 perform cp_observe(i,r,'feed_intake','warning','Reduced interval feed intake','Matched-interval feed consumption per bird/hour fell below the configured recent baseline.','Verify measured consumption, interval boundaries, feeder access, wastage, light schedule and bird activity.',r.derived,jsonb_build_object('baselineRate',df,'dropPct',rules->'intakeDropPct','source','Own matched checkpoint intervals'),coalesce(lowfeed,false),baseline_count>=3 and (r.derived->>'feedRate')::numeric>=df*(1-coalesce((rules->>'intakeRecoveryPct')::numeric,5)/100));
 perform cp_observe(i,r,'water_intake','warning','Reduced interval water intake','Matched-interval water consumption per bird/hour fell below the configured recent baseline.','Check meter/reset, actual interval, leaks, supply, nipple flow and temperature; never restrict drinking access.',r.derived,jsonb_build_object('baselineRate',dw,'dropPct',rules->'intakeDropPct','source','Own matched checkpoint intervals'),coalesce(lowwater,false),baseline_count>=3 and (r.derived->>'waterRate')::numeric>=dw*(1-coalesce((rules->>'intakeRecoveryPct')::numeric,5)/100));
 perform cp_observe(i,r,'high_feed_intake','warning','Unusually high interval feed disappearance','Matched interval feed rate exceeds the configured recent baseline; this can reflect spillage or recording problems.','Check quantities, wastage, feeder settings and actual access before interpreting performance.',r.derived,jsonb_build_object('baselineRate',df,'risePct',coalesce(rules->'intakeRisePct','30'::jsonb)),coalesce(highfeed,false),baseline_count>=3 and (r.derived->>'feedRate')::numeric between df*.95 and df*1.05);
 perform cp_observe(i,r,'high_water_intake','warning','Unusually high interval water use','Matched interval water rate exceeds the configured recent baseline; check heat, leaks and access.','Check meter resets, leaks, cooling-water separation, temperature and humidity; do not restrict water to meet the baseline.',r.derived,jsonb_build_object('baselineRate',dw,'risePct',coalesce(rules->'intakeRisePct','30'::jsonb)),coalesce(highwater,false),baseline_count>=3 and (r.derived->>'waterRate')::numeric between dw*.95 and dw*1.05);
 n=cp_num(r.payload,'deaths');mortalitybad=coalesce((r.payload->>'openingBirds')::numeric>0 and n/(r.payload->>'openingBirds')::numeric*100>=(rules->>'mortalityCriticalPct')::numeric,false);
 perform cp_observe(i,r,'mortality',case when mortalitybad then 'critical' else 'warning' end,'Mortality requires investigation','New deaths crossed an approved action threshold or rose against matched intervals. Mortality does not identify a disease.','Contact the veterinarian promptly; check water, ventilation and equipment while arranging examination. Do not wait for another day or choose medicines from environmental readings.',jsonb_build_object('deaths',n,'openingBirds',r.payload->'openingBirds','interval',r.derived),rules,mortalitybad or coalesce(baseline_count>=3 and dm>0 and (r.derived->>'mortalityRate')::numeric>dm*1.5,false),n=0);
 perform cp_observe(i,r,'combined_heat','critical','High heat + humidity + panting','Interacting conditions can make heat loss difficult.','Check drinking water, airflow, fans and cooling immediately; evaluate humidity before adding evaporation. Seek veterinary assistance if distress persists.',jsonb_build_object('temperature',temp_,'humidity',rh,'signs',signals),band,coalesce((temp_>(band#>>'{temperature,warningMax}')::numeric or exists(select 1 from jsonb_array_elements(coalesce(r.payload->'locations','[]')) l where (l->>'temperature')::numeric>(band#>>'{temperature,warningMax}')::numeric)) and rh>(band#>>'{humidity,warningMax}')::numeric and 'panting'=any(signals),false),coalesce(temp_ between (band#>>'{temperature,recoveryMin}')::numeric and (band#>>'{temperature,recoveryMax}')::numeric and rh between (band#>>'{humidity,recoveryMin}')::numeric and (band#>>'{humidity,recoveryMax}')::numeric and not 'panting'=any(signals),false));
 perform cp_observe(i,r,'combined_air','critical','High ammonia + wet litter + poor ventilation','The combined air/litter findings require prompt corrective action.','Check ventilation failure and wet-litter/leak sources together; keep personnel safe and contact the manager.',jsonb_build_object('ammonia',nh,'litter',r.payload#>'{states,litter}','ventilation',r.payload#>'{states,ventilation}'),lim,coalesce(nh>=(lim->>'ammoniaWarning')::numeric and r.payload#>>'{states,litter}' in ('wet','caked') and r.payload#>>'{states,ventilation}'='failed',false),coalesce(nh<=(lim->>'ammoniaRecovery')::numeric and r.payload#>>'{states,litter}'='dry' and r.payload#>>'{states,ventilation}'='ok',false));
 perform cp_observe(i,r,'combined_intake','warning','Reduced feed and water intake together','Matched per-bird interval rates fell together.','Check access, supply interruptions, lighting, interval recording and flock behavior; discuss persistent reductions with the veterinarian.',r.derived,rules,coalesce(lowfeed and lowwater,false),baseline_count>=3 and not coalesce(lowfeed or lowwater,true));
 perform cp_observe(i,r,'combined_mortality','critical','Rising mortality + respiratory signs','Concurrent losses and breathing signs need urgent veterinary investigation, not a photo-only diagnosis.','Contact the company veterinarian immediately, check equipment and safe air supply, limit unnecessary shed-to-shed movements and follow local reporting guidance.',jsonb_build_object('deaths',n,'signs',signals),rules,coalesce((mortalitybad or baseline_count>=3 and (r.derived->>'mortalityRate')::numeric>dm*1.5) and respiratory,false),n=0 and not respiratory);
end $$;
revoke all on function cp_validate_profile(jsonb) from public,anon,authenticated;
